from pathlib import Path
p=Path('js/modules/management.js');s=p.read_text(encoding='utf-8')
tp=Path('tests/management-separate-pages.test.js');test=tp.read_text(encoding='utf-8')

old="_yetkiKontrol(){if(!duzenleyebilir('nobet')){toast?.('Bu işlem için yetkiniz yok.');return false}return true},"
new="_yetkiKontrol(){const ok=global.PermissionService?.can?.('management.duty.edit','edit')??(typeof duzenleyebilir==='function'&&duzenleyebilir('nobet'));if(!ok){toast?.('Bu işlem için yetkiniz yok.');return false}return true},"
if old not in s: raise SystemExit('NobetService permission kalıbı bulunamadı')
s=s.replace(old,new,1)

old="${edit?'<button class=\"ka-btn ka-btn--secondary ka-btn--sm\" type=\"button\" data-duty-place-add>+ Yeni Nöbet Yeri</button>':''}<button class=\"ka-btn ka-btn--secondary ka-btn--sm\" type=\"button\" data-duty-report>🖨️ Nöbet Listesi</button>"
new="${edit?'<button class=\"ka-btn ka-btn--secondary ka-btn--sm\" type=\"button\" data-duty-places>📍 Nöbet Yerleri</button><button class=\"ka-btn ka-btn--secondary ka-btn--sm\" type=\"button\" data-duty-excel>📥 Excel’den İçe Aktar</button>':''}<button class=\"ka-btn ka-btn--secondary ka-btn--sm\" type=\"button\" data-duty-report>🖨️ Nöbet Listesi</button>"
if old not in s: raise SystemExit('Duty action bar bulunamadı')
s=s.replace(old,new,1)

anchor='function placeModal(){'
i=s.find(anchor)
if i<0: raise SystemExit('placeModal anchor bulunamadı')
block=r'''async function ensureDutyXlsx(){if(globalThis.XLSX)return globalThis.XLSX;await globalThis.AppLoader?.loadScript?.('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js');if(!globalThis.XLSX)throw new Error('Excel okuma kütüphanesi yüklenemedi.');return globalThis.XLSX}
function dutyPlacesModal(){const places=NobetService.yerSirali(arr('nobetYerleri')),ov=modal('📍 Nöbet Yerleri',`<div class="ka-stack">${places.length?places.map(p=>`<div class="ka-duty-holiday"><span class="ka-grow"><strong>${esc(p.ad||'Nöbet Yeri')}</strong></span><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-duty-place-edit="${esc(p.id)}">Düzenle</button><button class="ka-btn ka-btn--danger ka-btn--sm" type="button" data-duty-place-delete="${esc(p.id)}">Sil</button></div>`).join(''):'<div class="ka-empty">Henüz nöbet yeri tanımlanmadı.</div>'}</div><button class="ka-btn" type="button" data-duty-place-new>＋ Yeni Nöbet Yeri</button>`);ov.querySelector('[data-save]').hidden=true;ov.querySelector('[data-duty-place-new]').onclick=()=>{ov.remove();placeModal()};ov.querySelectorAll('[data-duty-place-edit]').forEach(b=>b.onclick=()=>{const item=places.find(x=>x.id===b.dataset.dutyPlaceEdit);if(!item)return;const e=modal('Nöbet Yerini Düzenle',`<label class="ka-field"><span class="ka-field__label">Nöbet yeri adı</span><input data-name value="${esc(item.ad||'')}"></label>`);e.querySelector('[data-save]').onclick=async()=>{const ad=e.querySelector('[data-name]').value.trim().replace(/\s+/g,' ');if(!ad)return;await NobetService.yeriGuncelle(item.id,ad);e.remove();dutyPlacesModal()}});ov.querySelectorAll('[data-duty-place-delete]').forEach(b=>b.onclick=async()=>{const item=places.find(x=>x.id===b.dataset.dutyPlaceDelete);if(!item)return;const linked=arr('nobetAtamalari').filter(x=>x.yerId===item.id);if(!confirm(`“${item.ad}” nöbet yeri${linked.length?` ve bağlı ${linked.length} atama`:''} silinsin mi?`))return;await NobetService.yeriSil(item.id,linked);ov.remove();dutyPlacesModal()})}
function dutyExcelMappingModal(sheetName,rows,headerIdx,dateCol,chiefCol,columns){const ov=modal(`Excel’den İçe Aktar — ${esc(sheetName)}`,`<p class="ka-muted">“${esc(sheetName)}” sayfası algılandı. Nöbetçi Amir sütunu otomatik bulundu. Nöbet yeri adlarını kontrol edin.</p><div class="ka-stack">${columns.map(c=>`<div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Sütun ${c.index+1}${c.sample?` — örn: ${esc(c.sample)}`:''}</span><input data-duty-excel-label="${c.index}" value="${esc(c.label)}"></label><label class="ka-field"><span class="ka-field__label">Kullanım</span><select data-duty-excel-role="${c.index}"><option value="place">Nöbet Yeri</option><option value="ignore">Yoksay</option></select></label></div>`).join('')}</div>`,'İçe Aktar');ov.querySelector('[data-save]').onclick=async()=>{const mappings=columns.map(c=>({index:c.index,etiket:ov.querySelector(`[data-duty-excel-label="${c.index}"]`).value.trim(),rol:ov.querySelector(`[data-duty-excel-role="${c.index}"]`).value})).filter(x=>x.rol==='place'&&x.etiket);if(!mappings.length)return toast?.('En az bir nöbet yeri eşlemesi gerekli.');ov.querySelector('[data-save]').disabled=true;try{const r=await NobetService.exceliUygula({satirlar:rows,baslikIdx:headerIdx,tarihCol:dateCol,amirCol:chiefCol,eslemeler:mappings,nobetYerleri:arr('nobetYerleri'),nobetAtamalari:arr('nobetAtamalari'),nobetciAmirleri:arr('nobetciAmirleri'),ogretmenler:arr('ogretmenler')});ov.remove();toast?.(`İçe aktarıldı: ${r.gunSayisi} gün · ${r.atamaSayisi} nöbet ataması · ${r.amirSayisi} amir ataması.`)}catch(e){ov.querySelector('[data-save]').disabled=false;toast?.(e?.message==='yetkisiz'?'Bu işlem için yetkiniz yok.':e?.message||'Excel içe aktarılamadı.')}}}
async function readDutyExcel(file){if(!file)return;try{const XLSX=await ensureDutyXlsx(),wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true}),sheets=wb.SheetNames.filter(n=>!/^veri$|^data$|^referans$/i.test(String(n).trim()));if(!sheets.length)throw new Error('Uygun ay sayfası bulunamadı.');const sheetName=sheets[sheets.length-1],rows=XLSX.utils.sheet_to_json(wb.Sheets[sheetName],{header:1,defval:''});let headerIdx=-1,chiefCol=-1;for(let i=0;i<Math.min(6,rows.length);i++){const c=(rows[i]||[]).findIndex(h=>/amir/i.test(String(h)));if(c>-1){headerIdx=i;chiefCol=c;break}}if(headerIdx<0)throw new Error(`“${sheetName}” sayfasında NÖBETÇİ AMİR başlığı bulunamadı.`);const found=(rows[headerIdx]||[]).findIndex(h=>/tarih|gün|date/i.test(String(h))),dateCol=found>-1?found:0,sub=rows[headerIdx+1]||[],sampleRow=rows.slice(headerIdx+2).find(r=>(r||[]).some(v=>v!==''))||[],columns=[];for(let c=dateCol+1;c<chiefCol;c++)columns.push({index:c,label:String(sub[c]||'').trim()||`Sütun ${c+1}`,sample:NobetService.excelAdiSadelestir(sampleRow[c]||'')});dutyExcelMappingModal(sheetName,rows,headerIdx,dateCol,chiefCol,columns)}catch(e){toast?.('Excel okunamadı: '+(e?.message||e))}}
function dutyExcelModal(){const ov=modal('📥 Nöbet Excel’den İçe Aktar','<p class="ka-muted">Excel dosyasındaki en güncel ay sekmesi kullanılır. “Nöbetçi Amir” ve tarih sütunları otomatik algılanır.</p><label class="ka-field"><span class="ka-field__label">Excel Dosyası</span><input type="file" data-duty-excel-file accept=".xlsx,.xls,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel"></label>');ov.querySelector('[data-save]').hidden=true;ov.querySelector('[data-duty-excel-file]').onchange=e=>{const file=e.target.files?.[0];if(file){ov.remove();readDutyExcel(file)}}}
'''
s=s[:i]+block+s[i:]

old="function bindDuty(){document.querySelector('[data-duty-place-add]')?.addEventListener('click',placeModal);document.querySelector('[data-duty-holiday-add]')?.addEventListener('click',holidayModal);"
new="function bindDuty(){document.querySelector('[data-duty-places]')?.addEventListener('click',dutyPlacesModal);document.querySelector('[data-duty-excel]')?.addEventListener('click',dutyExcelModal);document.querySelector('[data-duty-holiday-add]')?.addEventListener('click',holidayModal);"
if old not in s: raise SystemExit('bindDuty başlangıcı bulunamadı')
s=s.replace(old,new,1)

needle="for(const token of ['exceliUygula','otomatikDagitimUygula','defterDolduToggle','createDutyReport','DUTY_TASKS','data-duty-book','nobetYerleri','nobetAtamalari','nobetciAmirleri','resmiTatiller'])assert(management.includes(token),`Nöbet gerçek davranış sözleşmesi eksik: ${token}`);"
if needle not in test: raise SystemExit('Management duty test anchor bulunamadı')
extra=needle+"\nfor(const token of ['data-duty-places','data-duty-excel','dutyPlacesModal','dutyExcelModal','readDutyExcel','dutyExcelMappingModal','xlsx.full.min.js']) assert(management.includes(token),`Nöbet Excel/yer yönetimi sözleşmesi eksik: ${token}`);\nassert(management.includes(\"PermissionService?.can?.('management.duty.edit','edit')\"),'Nöbet servis yetkisi merkezi PermissionService kullanmalı.');\nassert(management.includes('AppLoader?.loadScript?.'),'Nöbet Excel kütüphanesi merkezi lazy loader ile yüklenmeli.');"
test=test.replace(needle,extra,1)

p.write_text(s,encoding='utf-8');tp.write_text(test,encoding='utf-8');print('Nöbet yer yönetimi + Excel içe aktarma gerçek eski davranışla taşındı.')
